      title: ['', ' \n ', null], completed: [1, 'true'], priority: ['Normal ', false],
      dueDate: ['1900-02-29', '2023-02-29', '0000-01-01', '10000-01-01', '2024-04-31', ' 2024-01-01', '2024-1-01', null],
      notes: [null, 12], deleted: [0, 'false'],
    })) {
